import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { toast } from 'react-hot-toast';
import { Printer, CheckCircle2, AlertTriangle } from 'lucide-react';
import apiClient from '../../utils/apiClient';
import { Card, Modal, Field, Pill, Pager, Stat, EmptyState, TableSkeleton, btnGhost, btnPrimary, btnDanger, inputCls, fmtDate, errMsg, pkr } from '../../components/ui';

const KINDS = ['teacher', 'admin', 'clerk', 'guard', 'cleaner', 'driver', 'technician', 'librarian', 'counselor', 'visiting', 'vendor'];
const TONE = { Active: 'Active', Onboarding: 'Pending', Separated: 'None', Requested: 'Pending', Approved: 'Approved', Rejected: 'Suspended', Cancelled: 'None', Draft: 'Pending', Reviewed: 'Active', Retired: 'None', Finalized: 'Paid', Settled: 'Confirmed', Open: 'Pending', Needed: 'Pending', Assigned: 'Confirmed', Cleared: 'None' };
const useList = (path, key, params) => {
  const [s, setS] = useState({ rows: [], pagination: null, loading: true, error: '' }); const [page, setPage] = useState(1); const q = JSON.stringify(params || {});
  const load = useCallback(async () => { setS((x) => ({ ...x, loading: true })); try { const r = await apiClient.get(path, { params: { page, ...JSON.parse(q) } }); const p = r.data.pagination; setS({ rows: r.data[key] || [], pagination: p && { ...p, currentPage: p.page }, loading: false, error: '' }); } catch (e) { setS((x) => ({ ...x, loading: false, error: errMsg(e, 'Could not load') })); } }, [path, key, page, q]);
  useEffect(() => { load(); }, [load]); useEffect(() => { setPage(1); }, [q]);
  return { ...s, setPage, reload: load };
};
const Body = ({ l, cols, empty, children }) => (l.loading ? <TableSkeleton cols={cols} /> : l.error ? <EmptyState title={l.error} action={<button className={btnGhost} onClick={l.reload}>Try again</button>} /> : !l.rows.length ? <EmptyState title={empty.title} text={empty.text} /> : children);
const Th = ({ children }) => <th className="px-3 py-2 text-start text-xs font-semibold uppercase tracking-wide text-[#5b6b7b]">{children}</th>;
const Tbl = ({ head, children }) => <div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr>{head.map((h, i) => <Th key={i}>{h}</Th>)}</tr></thead><tbody>{children}</tbody></table></div>;
const Td = ({ children, cls = '' }) => <td className={`px-3 py-2 ${cls}`}>{children}</td>;
const Row = ({ children }) => <tr className="border-t border-[#e3e7e7]">{children}</tr>;
const Bar = ({ children }) => <div className="flex flex-wrap items-center gap-2 border-b border-[#e3e7e7] p-3">{children}</div>;
const useEmployees = (all) => { const [e, setE] = useState([]); useEffect(() => { apiClient.get('/hr/employees', { params: { limit: 100, ...(all ? {} : { status: 'Active' }) } }).then((r) => setE(r.data.employees || [])).catch(() => {}); }, [all]); return e; };
const EmpSelect = ({ value, onChange, emps }) => <select className={inputCls} value={value} onChange={(e) => onChange(e.target.value)}><option value="">Choose a person</option>{emps.map((e) => <option key={e._id} value={e._id}>{e.name} · {e.code}</option>)}</select>;
const act = (fn, ok, after) => async () => { try { await fn(); if (ok) toast.success(ok); after && after(); } catch (e) { toast.error(errMsg(e)); } };
const today = () => new Date().toISOString().slice(0, 10);

/* ───────── overview ───────── */
const Overview = ({ onGo }) => {
  const [o, setO] = useState(null); const [ex, setEx] = useState([]);
  useEffect(() => { apiClient.get('/hr/overview').then((r) => setO(r.data)).catch(() => {}); apiClient.get('/hr/expiring', { params: { days: 60 } }).then((r) => setEx(r.data.items)).catch(() => {}); }, []);
  if (!o) return <div className="skeleton h-32" />;
  return (
    <div className="space-y-4">
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Stat label="Staff" value={o.headcount.total} sub={`${o.headcount.byStatus.Onboarding || 0} onboarding`} /><Stat label="Present today" value={(o.today.Present || 0) + (o.today.Late || 0)} sub={`${o.today.Absent || 0} absent`} /><Stat label="Leave to decide" value={o.pending.leave} tone={o.pending.leave ? 'text-[#8a4636]' : undefined} /><Stat label="Expiring in 60 days" value={o.expiring} sub="Documents, training, contracts" /></div>
      <div className="grid gap-3 sm:grid-cols-3"><button className="text-start" onClick={() => onGo('time')}><Stat label="Overtime and advances waiting" value={o.pending.overtime + o.pending.advances} /></button><button className="text-start" onClick={() => onGo('payroll')}><Stat label="Pay rules to review" value={o.pending.payrollRules} sub="Must be reviewed before payroll can be final" /></button><button className="text-start" onClick={() => onGo('leave')}><Stat label="Leave requests" value={o.pending.leave} /></button></div>
      <Card className="!p-0"><div className="border-b border-[#e3e7e7] p-3 font-semibold">Expiring soon</div>{ex.length ? <Tbl head={['Item', 'Person', 'Date', '']}>{ex.map((x, i) => <Row key={i}><Td>{x.title}<div className="text-xs capitalize text-[#5b6b7b]">{x.type}</div></Td><Td>{x.employee}</Td><Td>{fmtDate(x.on)}</Td><Td>{x.expired ? <Pill value="Suspended">Expired</Pill> : <Pill value="Pending">Soon</Pill>}</Td></Row>)}</Tbl> : <EmptyState title="Nothing expiring" text="Licences, mandatory training and fixed-term contracts due in the next 60 days appear here." />}</Card>
    </div>
  );
};

/* ───────── people ───────── */
const NewEmployee = ({ onClose, onDone }) => {
  const [f, setF] = useState({ name: '', kind: 'clerk', teacherId: '', positionId: '', basicSalary: '', phone: '', email: '', joinDate: today(), allow: '' }); const [teachers, setTeachers] = useState([]); const [pos, setPos] = useState([]);
  useEffect(() => { apiClient.get('/teachers', { params: { limit: 200 } }).then((r) => setTeachers(r.data.teachers || [])).catch(() => {}); apiClient.get('/hr/positions').then((r) => setPos(r.data.positions.filter((p) => p.status === 'Active'))).catch(() => {}); }, []);
  const set = (k) => (e) => setF({ ...f, [k]: e.target.value });
  const save = act(async () => { await apiClient.post('/hr/employees', { ...f, teacherId: f.teacherId || undefined, positionId: f.positionId || undefined, basicSalary: Number(f.basicSalary) || 0, allowances: f.allow ? [{ name: 'Allowance', amount: Number(f.allow), taxable: true }] : [] }); }, 'Added. Finish the onboarding checklist to start them.', () => { onDone(); onClose(); });
  return (
    <Modal title="Add a staff member" onClose={onClose}>
      <div className="grid gap-3 sm:grid-cols-2">
        <Field label="Full name"><input className={inputCls} value={f.name} onChange={set('name')} /></Field>
        <Field label="Kind"><select className={inputCls} value={f.kind} onChange={set('kind')}>{KINDS.map((k) => <option key={k}>{k}</option>)}</select></Field>
        {f.kind === 'teacher' && <Field label="Teacher account"><select className={inputCls} value={f.teacherId} onChange={set('teacherId')}><option value="">Choose</option>{teachers.map((t) => <option key={t._id} value={t._id}>{t.name}</option>)}</select></Field>}
        <Field label="Position" hint="The salary must fit the band"><select className={inputCls} value={f.positionId} onChange={set('positionId')}><option value="">None</option>{pos.map((p) => <option key={p._id} value={p._id}>{p.title}{p.salaryMax ? ` (${pkr(p.salaryMin)}–${pkr(p.salaryMax)})` : ''}</option>)}</select></Field>
        <Field label="Basic salary (Rs)"><input inputMode="numeric" className={inputCls} value={f.basicSalary} onChange={set('basicSalary')} /></Field>
        <Field label="Monthly allowance (Rs)"><input inputMode="numeric" className={inputCls} value={f.allow} onChange={set('allow')} /></Field>
        <Field label="Phone"><input className={inputCls} value={f.phone} onChange={set('phone')} /></Field><Field label="Joining date"><input type="date" className={inputCls} value={f.joinDate} onChange={set('joinDate')} /></Field>
      </div>
      <div className="mt-4 flex justify-end gap-2"><button className={btnGhost} onClick={onClose}>Cancel</button><button className={btnPrimary} disabled={f.name.trim().length < 2} onClick={save}>Add</button></div>
    </Modal>
  );
};
const EmployeeDetail = ({ id, onClose, onChanged }) => {
  const [d, setD] = useState(null); const [c, setC] = useState(null); const [r, setR] = useState(null); const [x, setX] = useState(null);
  const load = useCallback(() => apiClient.get(`/hr/employees/${id}`).then((r2) => setD(r2.data)).catch((e) => { toast.error(errMsg(e)); onClose(); }), [id, onClose]); useEffect(() => { load(); }, [load]);
  if (!d) return <Modal title="Staff member" onClose={onClose} wide><div className="skeleton h-40" /></Modal>; const e = d.employee; const reload = () => { load(); onChanged(); };
  return (
    <Modal title={`${e.name} · ${e.code}`} onClose={onClose} wide>
      <div className="space-y-5 text-sm">
        <div className="flex flex-wrap items-center gap-3"><Pill value={TONE[e.status]}>{e.status}</Pill><span className="capitalize text-[#5b6b7b]">{e.kind}{d.position ? ` · ${d.position.title}` : ''} · basic {pkr(e.basicSalary)}</span>{e.status === 'Onboarding' && <button className={`${btnPrimary} ms-auto`} onClick={act(() => apiClient.post(`/hr/employees/${id}/activate`), 'Started', reload)}>Start employment</button>}</div>
        {e.status === 'Onboarding' && <div><p className="font-semibold">Onboarding checklist</p><ul className="mt-2 space-y-1">{e.checklist.map((it) => <li key={it.key}><label className="flex items-center gap-2"><input type="checkbox" checked={it.done} onChange={(ev) => act(() => apiClient.put(`/hr/employees/${id}/checklist/${it.key}`, { done: ev.target.checked }), null, reload)()} />{it.label}{it.done && <span className="text-xs text-[#5b6b7b]">· {it.doneByName}</span>}</label></li>)}</ul></div>}
        <div><div className="flex items-center justify-between"><p className="font-semibold">Contracts</p>{e.status !== 'Separated' && <button className="text-xs font-semibold text-[#2a5cac]" onClick={() => setC({})}>New contract</button>}</div>
          {d.contracts.length ? <Tbl head={['Type', 'Start', 'End', 'Notice by', 'Status', '']}>{d.contracts.map((k) => <Row key={k._id}><Td className="capitalize">{k.type}</Td><Td>{fmtDate(k.startDate)}</Td><Td>{k.endDate ? fmtDate(k.endDate) : 'Open'}</Td><Td>{k.noticeBy ? fmtDate(k.noticeBy) : '—'}</Td><Td><Pill value={k.status === 'Signed' ? 'Active' : k.status === 'Draft' ? 'Pending' : 'None'}>{k.status}</Pill></Td><Td cls="text-end">{k.status === 'Draft' && <button className="text-xs font-semibold text-[#2a5cac]" onClick={act(() => apiClient.post(`/hr/contracts/${k._id}/sign`), 'Signed', reload)}>Sign</button>}{k.status === 'Signed' && <button className="text-xs font-semibold text-[#9f1239]" onClick={() => { const reason = window.prompt('Why does this contract end?'); if (reason) act(() => apiClient.post(`/hr/contracts/${k._id}/end`, { reason }), 'Ended', reload)(); }}>End</button>}</Td></Row>)}</Tbl> : <p className="mt-1 text-[#5b6b7b]">No contract yet.</p>}</div>
        <div><div className="flex items-center justify-between"><p className="font-semibold">Documents, training and reviews</p><button className="text-xs font-semibold text-[#2a5cac]" onClick={() => setR({ kind: 'document' })}>Add</button></div>
          {d.records.length ? <ul className="mt-2 divide-y divide-[#e3e7e7]">{d.records.map((k) => <li key={k._id} className="py-2"><b>{k.title}</b> <span className="capitalize text-[#5b6b7b]">· {k.kind}{k.mandatory ? ' · mandatory' : ''}</span>{k.expiresOn && <span className="text-[#5b6b7b]"> · expires {fmtDate(k.expiresOn)}</span>}{k.kind === 'appraisal' && <div className="text-xs text-[#5b6b7b]">Rating {k.rating || '—'} · {k.reviewerNotes}{k.goals?.length ? ` · Goals: ${k.goals.map((g) => g.text).join('; ')}` : ''}<div>{k.employeeResponse ? `Employee: ${k.employeeResponse}` : 'No response yet'}</div></div>}</li>)}</ul> : <p className="mt-1 text-[#5b6b7b]">Nothing on file.</p>}</div>
        <div><p className="font-semibold">Leave balance this year</p><p className="text-[#5b6b7b]">Annual {d.leave.annual.left} of {d.leave.annual.entitled} left · Sick {d.leave.sick.left} of {d.leave.sick.entitled} · Casual {d.leave.casual.left} of {d.leave.casual.entitled}</p></div>
        {e.status === 'Active' && <div className="flex justify-end"><button className={btnDanger} onClick={() => setX({})}>Start final settlement</button></div>}
      </div>
      {c && <NewContract id={id} onClose={() => setC(null)} onDone={reload} />}{r && <NewRecord id={id} onClose={() => setR(null)} onDone={reload} />}{x && <StartSettlement id={id} onClose={() => setX(null)} onDone={() => { reload(); }} />}
    </Modal>
  );
};
const NewContract = ({ id, onClose, onDone }) => { const [f, setF] = useState({ type: 'permanent', startDate: today(), endDate: '', noticeDays: 30 }); const set = (k) => (e) => setF({ ...f, [k]: e.target.value }); return (
  <Modal title="New contract" onClose={onClose}><div className="grid gap-3 sm:grid-cols-2"><Field label="Type"><select className={inputCls} value={f.type} onChange={set('type')}>{['permanent', 'fixed-term', 'visiting', 'vendor'].map((t) => <option key={t}>{t}</option>)}</select></Field><Field label="Notice (days)"><input inputMode="numeric" className={inputCls} value={f.noticeDays} onChange={set('noticeDays')} /></Field><Field label="Start"><input type="date" className={inputCls} value={f.startDate} onChange={set('startDate')} /></Field><Field label="End" hint="Needed unless permanent"><input type="date" className={inputCls} value={f.endDate} onChange={set('endDate')} /></Field></div>
    <div className="mt-4 flex justify-end gap-2"><button className={btnGhost} onClick={onClose}>Cancel</button><button className={btnPrimary} onClick={act(() => apiClient.post('/hr/contracts', { employeeId: id, ...f, endDate: f.endDate || undefined, noticeDays: Number(f.noticeDays) }), 'Draft saved. Sign it to make it live.', () => { onDone(); onClose(); })}>Save draft</button></div></Modal>); };
const NewRecord = ({ id, onClose, onDone }) => { const [f, setF] = useState({ kind: 'document', title: '', issuedOn: '', expiresOn: '', mandatory: false, goals: '', consent: false, rating: '', notes: '' }); const set = (k) => (e) => setF({ ...f, [k]: e.target.type === 'checkbox' ? e.target.checked : e.target.value }); return (
  <Modal title="Add to the file" onClose={onClose}><div className="grid gap-3 sm:grid-cols-2"><Field label="Kind"><select className={inputCls} value={f.kind} onChange={set('kind')}><option value="document">Document or licence</option><option value="training">Training</option><option value="appraisal">Appraisal</option></select></Field><Field label="Title"><input className={inputCls} value={f.title} onChange={set('title')} /></Field>
    {f.kind !== 'appraisal' && <><Field label="Issued"><input type="date" className={inputCls} value={f.issuedOn} onChange={set('issuedOn')} /></Field><Field label="Expires"><input type="date" className={inputCls} value={f.expiresOn} onChange={set('expiresOn')} /></Field></>}
    {f.kind === 'training' && <label className="flex items-center gap-2 text-sm sm:col-span-2"><input type="checkbox" checked={f.mandatory} onChange={set('mandatory')} />Mandatory. An expired one stops them covering classes.</label>}
    {f.kind === 'appraisal' && <><Field label="Rating (1 to 5)"><input inputMode="numeric" className={inputCls} value={f.rating} onChange={set('rating')} /></Field><Field label="Goals, one per line"><textarea rows={3} className={inputCls} value={f.goals} onChange={set('goals')} /></Field><div className="sm:col-span-2"><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={f.consent} onChange={set('consent')} />The employee has agreed to these goals</label></div><div className="sm:col-span-2"><Field label="Reviewer notes"><textarea rows={3} className={inputCls} value={f.notes} onChange={set('notes')} /></Field></div></>}
  </div><div className="mt-4 flex justify-end gap-2"><button className={btnGhost} onClick={onClose}>Cancel</button><button className={btnPrimary} disabled={f.title.trim().length < 2} onClick={act(() => apiClient.post(`/hr/employees/${id}/records`, { kind: f.kind, title: f.title, issuedOn: f.issuedOn || undefined, expiresOn: f.expiresOn || undefined, mandatory: f.mandatory, goals: f.goals.split('\n').map((g) => g.trim()).filter(Boolean), goalsConsented: f.consent, rating: f.rating ? Number(f.rating) : undefined, reviewerNotes: f.notes }), 'Saved', () => { onDone(); onClose(); })}>Save</button></div></Modal>); };
const StartSettlement = ({ id, onClose, onDone }) => { const [f, setF] = useState({ lastDay: today(), reason: '' }); return (
  <Modal title="Final settlement" onClose={onClose}><Field label="Last working day"><input type="date" className={inputCls} value={f.lastDay} onChange={(e) => setF({ ...f, lastDay: e.target.value })} /></Field><Field label="Reason for leaving"><input className={inputCls} value={f.reason} onChange={(e) => setF({ ...f, reason: e.target.value })} /></Field>
    <div className="mt-4 flex justify-end gap-2"><button className={btnGhost} onClick={onClose}>Cancel</button><button className={btnPrimary} disabled={f.reason.trim().length < 3} onClick={act(() => apiClient.post('/hr/settlements', { employeeId: id, ...f }), 'Settlement started. Finish it on the Exits tab.', () => { onDone(); onClose(); })}>Start</button></div></Modal>); };

const People = () => {
  const [status, setStatus] = useState(''); const [kind, setKind] = useState(''); const [search, setSearch] = useState(''); const [add, setAdd] = useState(false); const [show, setShow] = useState(null); const l = useList('/hr/employees', 'employees', { status, kind, search });
  return (
    <Card className="!p-0"><Bar><input className={`${inputCls} !w-52`} placeholder="Search by name" value={search} onChange={(e) => setSearch(e.target.value)} /><select className={`${inputCls} !w-36`} value={status} onChange={(e) => setStatus(e.target.value)}><option value="">All</option>{['Onboarding', 'Active', 'Separated'].map((s) => <option key={s}>{s}</option>)}</select><select className={`${inputCls} !w-36`} value={kind} onChange={(e) => setKind(e.target.value)}><option value="">All kinds</option>{KINDS.map((k) => <option key={k}>{k}</option>)}</select><button className={`${btnPrimary} ms-auto`} onClick={() => setAdd(true)}>Add staff</button></Bar>
      <Body l={l} cols={5} empty={{ title: 'No staff yet', text: 'Add teachers and non-teaching staff to run roster, leave and payroll.' }}><Tbl head={['Name', 'Kind', 'Department', 'Basic', 'Status']}>{l.rows.map((e) => <Row key={e._id}><Td><button className="font-medium text-[#2a5cac]" onClick={() => setShow(e._id)}>{e.name}</button><div className="text-xs text-[#5b6b7b]">{e.code}</div></Td><Td cls="capitalize">{e.kind}</Td><Td>{e.department || '—'}</Td><Td cls="" ><span dir="ltr">{pkr(e.basicSalary)}</span></Td><Td><Pill value={TONE[e.status]}>{e.status}</Pill></Td></Row>)}</Tbl><Pager pagination={l.pagination} onPage={l.setPage} /></Body>
      {add && <NewEmployee onClose={() => setAdd(false)} onDone={l.reload} />}{show && <EmployeeDetail id={show} onClose={() => setShow(null)} onChanged={l.reload} />}</Card>
  );
};

/* ───────── roster and attendance ───────── */
const Roster = () => {
  const emps = useEmployees(); const [shifts, setShifts] = useState([]); const [rows, setRows] = useState([]); const [f, setF] = useState({ employeeId: '', shiftId: '', from: today(), days: 6 }); const [res, setRes] = useState(null);
  const monday = useMemo(() => { const d = new Date(); d.setDate(d.getDate() + ((8 - d.getDay()) % 7 || 7)); return d.toISOString().slice(0, 10); }, []); const [from, setFrom] = useState(monday);
  const to = new Date(new Date(`${from}T00:00:00Z`).getTime() + 6 * 864e5).toISOString().slice(0, 10);
  const load = useCallback(() => { apiClient.get('/hr/shifts').then((r) => setShifts(r.data.shifts)).catch(() => {}); apiClient.get('/hr/roster', { params: { from, to } }).then((r) => setRows(r.data.roster)).catch(() => {}); }, [from, to]); useEffect(() => { load(); }, [load]);
  const dates = Array.from({ length: 7 }, (_, i) => new Date(new Date(`${from}T00:00:00Z`).getTime() + i * 864e5).toISOString().slice(0, 10)); const names = [...new Set(rows.map((r) => r.employeeName))];
  const assign = async () => { try { const r = await apiClient.post('/hr/roster', { employeeIds: [f.employeeId], shiftId: f.shiftId, dates }); setRes(r.data); toast.success(`${r.data.assigned} days rostered`); load(); } catch (e) { toast.error(errMsg(e)); } };
  const [ns, setNs] = useState(null);
  return (
    <div className="space-y-4">
      <Card><div className="flex flex-wrap items-end gap-3"><Field label="Week starting"><input type="date" className={`${inputCls} !w-44`} value={from} onChange={(e) => setFrom(e.target.value)} /></Field><Field label="Person"><div className="w-56"><EmpSelect emps={emps} value={f.employeeId} onChange={(v) => setF({ ...f, employeeId: v })} /></div></Field><Field label="Shift"><select className={`${inputCls} !w-48`} value={f.shiftId} onChange={(e) => setF({ ...f, shiftId: e.target.value })}><option value="">Choose</option>{shifts.map((s) => <option key={s._id} value={s._id}>{s.name} {s.startTime}-{s.endTime}</option>)}</select></Field><button className={btnPrimary} disabled={!f.employeeId || !f.shiftId} onClick={assign}>Roster this week</button><button className={btnGhost} onClick={() => setNs({ name: '', startTime: '08:00', endTime: '16:00', breakMinutes: 30 })}>New shift</button><button className={btnGhost} onClick={act(async () => { const r = await apiClient.post('/hr/roster/publish', { from, to }); toast(`${r.data.published} days published`); }, null, load)}>Publish week</button></div>
        {res && <div className="mt-3 space-y-1 text-sm">{res.warnings.map((w, i) => <p key={i} className="flex items-center gap-2 text-[#8a4636]"><AlertTriangle className="h-4 w-4" />{w}</p>)}{res.skipped.length > 0 && <p className="text-[#5b6b7b]">Skipped: {res.skipped.slice(0, 6).map((s) => `${s.employee} ${s.date || ''} (${s.why})`).join('; ')}</p>}</div>}</Card>
      <Card className="!p-0">{names.length ? <Tbl head={['Person', ...dates.map((d) => `${new Date(`${d}T00:00:00Z`).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric' })}`)]}>{names.map((n) => <Row key={n}><Td cls="font-medium">{n}</Td>{dates.map((d) => { const r = rows.find((x) => x.employeeName === n && x.date === d); return <Td key={d}>{r ? <span className={r.status === 'Draft' ? 'text-[#8a4636]' : ''}>{r.startTime}-{r.endTime}{r.status === 'Draft' ? ' (draft)' : ''}</span> : '—'}</Td>; })}</Row>)}</Tbl> : <EmptyState title="Nobody rostered this week" text="Pick a person and a shift. Drafts are invisible to staff until you publish." />}</Card>
      {ns && <Modal title="New shift" onClose={() => setNs(null)}><div className="grid gap-3 sm:grid-cols-2"><Field label="Name"><input className={inputCls} value={ns.name} onChange={(e) => setNs({ ...ns, name: e.target.value })} /></Field><Field label="Break (minutes)"><input inputMode="numeric" className={inputCls} value={ns.breakMinutes} onChange={(e) => setNs({ ...ns, breakMinutes: e.target.value })} /></Field><Field label="Starts"><input type="time" className={inputCls} value={ns.startTime} onChange={(e) => setNs({ ...ns, startTime: e.target.value })} /></Field><Field label="Ends"><input type="time" className={inputCls} value={ns.endTime} onChange={(e) => setNs({ ...ns, endTime: e.target.value })} /></Field></div><div className="mt-4 flex justify-end gap-2"><button className={btnGhost} onClick={() => setNs(null)}>Cancel</button><button className={btnPrimary} onClick={act(() => apiClient.post('/hr/shifts', { ...ns, breakMinutes: Number(ns.breakMinutes) }), 'Shift saved', () => { setNs(null); load(); })}>Save</button></div></Modal>}
    </div>
  );
};
const Attendance = () => {
  const [date, setDate] = useState(today()); const [d, setD] = useState(null); const [fix, setFix] = useState(null); const load = useCallback(() => apiClient.get('/hr/attendance', { params: { date } }).then((r) => setD(r.data)).catch((e) => toast.error(errMsg(e))), [date]); useEffect(() => { load(); }, [load]);
  const mark = (row, status, extra = {}) => act(() => apiClient.post('/hr/attendance', { employeeId: row.employeeId, date, status, ...extra }), 'Saved', load)();
  return (
    <Card className="!p-0"><Bar><input type="date" className={`${inputCls} !w-44`} value={date} max={today()} onChange={(e) => setDate(e.target.value)} /><p className="text-sm text-[#5b6b7b]">Changing a recorded day needs a reason and is kept.</p></Bar>
      {!d ? <TableSkeleton cols={4} /> : !d.rows.length ? <EmptyState title="No active staff" /> : <Tbl head={['Person', 'Rostered', 'Status', '']}>{d.rows.map((r) => <Row key={r.employeeId}><Td><b>{r.name}</b><div className="text-xs capitalize text-[#5b6b7b]">{r.kind}</div></Td><Td>{r.onLeave ? <Pill value="Approved">On leave</Pill> : r.rostered || '—'}</Td><Td>{r.attendance ? <Pill value={r.attendance.status === 'Absent' ? 'Suspended' : r.attendance.status === 'Late' ? 'Pending' : 'Confirmed'}>{r.attendance.status}{r.attendance.lateMinutes ? ` ${r.attendance.lateMinutes}m` : ''}</Pill> : <span className="text-[#5b6b7b]">Not recorded</span>}</Td>
        <Td cls="text-end whitespace-nowrap">{!r.onLeave && ['Present', 'Late', 'HalfDay', 'Absent'].map((s) => <button key={s} className="ms-3 text-xs font-semibold text-[#2a5cac]" onClick={() => (r.attendance && r.attendance.status !== s ? setFix({ row: r, status: s, reason: '' }) : !r.attendance && mark(r, s))}>{s === 'HalfDay' ? 'Half' : s}</button>)}</Td></Row>)}</Tbl>}
      {fix && <Modal title={`Change ${fix.row.name} to ${fix.status}`} onClose={() => setFix(null)}><Field label="Why is it being changed?"><input className={inputCls} value={fix.reason} onChange={(e) => setFix({ ...fix, reason: e.target.value })} /></Field><div className="mt-4 flex justify-end gap-2"><button className={btnGhost} onClick={() => setFix(null)}>Cancel</button><button className={btnPrimary} disabled={fix.reason.trim().length < 5} onClick={() => { mark(fix.row, fix.status, { reason: fix.reason }); setFix(null); }}>Change</button></div></Modal>}
    </Card>
  );
};

/* ───────── leave and cover ───────── */
const Leave = () => {
  const emps = useEmployees(); const [status, setStatus] = useState(''); const l = useList('/hr/leave', 'leave', { status }); const [add, setAdd] = useState(null); const [cv, setCv] = useState([]); const [pick, setPick] = useState(null); const [cands, setCands] = useState([]); const [note, setNote] = useState('');
  const loadCv = useCallback(() => apiClient.get('/hr/cover', { params: { from: today() } }).then((r) => setCv(r.data.cover)).catch(() => {}), []); useEffect(() => { loadCv(); }, [loadCv]);
  const decide = (x, decision) => act(() => apiClient.post(`/hr/leave/${x._id}/decide`, { decision, note: decision === 'reject' ? window.prompt('Why is it rejected?') || '' : '' }), decision === 'approve' ? 'Approved' : 'Rejected', () => { l.reload(); loadCv(); })();
  const openPick = async (c) => { setPick(c); setCands([]); try { setCands((await apiClient.get(`/hr/cover/${c._id}/candidates`)).data.candidates); } catch (e) { toast.error(errMsg(e)); } };
  return (
    <div className="space-y-4">
      <Card className="!p-0"><Bar><select aria-label="Show which leave requests" className={`${inputCls} !w-40`} value={status} onChange={(e) => setStatus(e.target.value)}><option value="">All requests</option>{['Requested', 'Approved', 'Rejected', 'Cancelled'].map((s) => <option key={s}>{s}</option>)}</select><button className={`${btnPrimary} ms-auto`} onClick={() => setAdd({ employeeId: '', type: 'annual', fromDate: today(), toDate: today(), reason: '' })}>Record leave</button></Bar>
        <Body l={l} cols={5} empty={{ title: 'No leave requests' }}><Tbl head={['Person', 'Kind', 'Dates', 'Days', 'Status', '']}>{l.rows.map((x) => <Row key={x._id}><Td><b>{x.employeeName}</b><div className="text-xs text-[#5b6b7b]">{x.reason}</div>{x.onBehalf && <div className="text-[11px] text-[#5b6b7b]">recorded by {x.requestedByName || 'the office'}</div>}{x.soleApproval && <div className="text-[11px] text-[#8a5a00]">approved by the only administrator</div>}</Td><Td cls="capitalize">{x.type}</Td><Td>{x.fromDate} to {x.toDate}</Td><Td>{x.days}</Td><Td><Pill value={TONE[x.status]}>{x.status}</Pill></Td><Td cls="text-end whitespace-nowrap">{x.status === 'Requested' && (x.canDecide ? <><button className="text-xs font-semibold text-[#2a5cac]" onClick={() => decide(x, 'approve')}>Approve</button><button className="ms-3 text-xs font-semibold text-[#9f1239]" onClick={() => decide(x, 'reject')}>Reject</button></> : <span className="text-xs text-[#5b6b7b]" title={x.blockedReason}>Waiting for another administrator</span>)}{x.status === 'Approved' && <button className="text-xs font-semibold text-[#5b6b7b]" onClick={act(() => apiClient.post(`/hr/leave/${x._id}/cancel`), 'Cancelled', () => { l.reload(); loadCv(); })}>Cancel</button>}</Td></Row>)}</Tbl><Pager pagination={l.pagination} onPage={l.setPage} /></Body></Card>
      <Card className="!p-0"><div className="border-b border-[#e3e7e7] p-3"><p className="font-semibold">Lessons that need cover</p><p className="text-sm text-[#5b6b7b]">Only teachers who are free, on duty and in date with mandatory training are offered.</p></div>
        {cv.length ? <Tbl head={['Date', 'Lesson', 'Away', 'Cover', '']}>{cv.map((c) => <Row key={c._id}><Td>{c.date}</Td><Td>{c.startTime}-{c.endTime} · class {c.className}</Td><Td>{c.absentName}</Td><Td>{c.coverName ? <Pill value="Confirmed">{c.coverName}</Pill> : <Pill value="Pending">Needed</Pill>}</Td><Td cls="text-end">{c.status === 'Needed' ? <button className="text-xs font-semibold text-[#2a5cac]" onClick={() => openPick(c)}>Find cover</button> : <button className="text-xs font-semibold text-[#5b6b7b]" onClick={act(() => apiClient.post(`/hr/cover/${c._id}/assign`, { unassign: true }), 'Removed', loadCv)}>Remove</button>}</Td></Row>)}</Tbl> : <EmptyState title="No cover needed" text="Approved leave for a teacher creates one line for each lesson they would have taught." />}</Card>
      {pick && <Modal title={`Cover ${pick.startTime} on ${pick.date}`} onClose={() => setPick(null)}>{cands.length ? <div className="space-y-1">{cands.map((t) => <button key={t._id} className="flex w-full justify-between rounded-lg border border-[#e3e7e7] px-3 py-2 text-start text-sm hover:bg-[#f7f6f2]" onClick={act(() => apiClient.post(`/hr/cover/${pick._id}/assign`, { coverTeacherId: t._id }), 'Assigned and notified', () => { setPick(null); loadCv(); })}>{t.name}<span className="text-[#2a5cac]">Assign</span></button>)}</div> : <p className="text-sm text-[#5b6b7b]">No teacher is free for this lesson.</p>}</Modal>}
      {add && <Modal title="Record leave" onClose={() => setAdd(null)}><p className="mb-3 text-sm text-[#5b6b7b]">For a paper form somebody handed in. It is saved as a request, and another administrator approves it — the person who writes it down does not also approve it. Staff can ask for leave themselves from their own page.</p><div className="grid gap-3 sm:grid-cols-2"><Field label="Person"><EmpSelect emps={emps} value={add.employeeId} onChange={(v) => setAdd({ ...add, employeeId: v })} /></Field><Field label="Kind"><select className={inputCls} value={add.type} onChange={(e) => setAdd({ ...add, type: e.target.value })}>{['annual', 'sick', 'casual', 'unpaid'].map((t) => <option key={t}>{t}</option>)}</select></Field><Field label="From"><input type="date" className={inputCls} value={add.fromDate} onChange={(e) => setAdd({ ...add, fromDate: e.target.value })} /></Field><Field label="To"><input type="date" className={inputCls} value={add.toDate} onChange={(e) => setAdd({ ...add, toDate: e.target.value })} /></Field></div><Field label="Reason"><input className={inputCls} value={add.reason} onChange={(e) => setAdd({ ...add, reason: e.target.value })} /></Field><div className="mt-4 flex justify-end gap-2"><button className={btnGhost} onClick={() => setAdd(null)}>Cancel</button><button className={btnPrimary} disabled={!add.employeeId || add.reason.trim().length < 3} onClick={act(() => apiClient.post('/hr/leave', add), 'Recorded', () => { setAdd(null); l.reload(); })}>Save</button></div></Modal>}
    </div>
  );
};

/* ───────── overtime and advances ───────── */
const Time = () => {
  const emps = useEmployees(); const ot = useList('/hr/overtime', 'overtime'); const adv = useList('/hr/advances', 'advances'); const [a, setA] = useState(null);
  const decide = (kind, x, decision, reload) => act(() => apiClient.post(`/hr/${kind}/${x._id}/decide`, { decision }), decision === 'approve' ? 'Approved' : 'Rejected', reload)();
  return (
    <div className="space-y-4">
      <Card className="!p-0"><Bar><p className="text-sm text-[#5b6b7b]">Only approved overtime reaches payroll. Another admin must approve.</p><button className={`${btnPrimary} ms-auto`} onClick={() => setA({ kind: 'overtime', employeeId: '', date: today(), hours: '1', reason: '' })}>Record overtime</button></Bar>
        <Body l={ot} cols={5} empty={{ title: 'No overtime' }}><Tbl head={['Person', 'Day', 'Hours', 'Reason', 'Status', '']}>{ot.rows.map((x) => <Row key={x._id}><Td>{x.employeeName}</Td><Td>{x.date}</Td><Td>{x.hours}</Td><Td>{x.reason}</Td><Td><Pill value={TONE[x.status]}>{x.status}</Pill></Td><Td cls="text-end whitespace-nowrap">{x.status === 'Requested' && <><button className="text-xs font-semibold text-[#2a5cac]" onClick={() => decide('overtime', x, 'approve', ot.reload)}>Approve</button><button className="ms-3 text-xs font-semibold text-[#9f1239]" onClick={() => decide('overtime', x, 'reject', ot.reload)}>Reject</button></>}</Td></Row>)}</Tbl><Pager pagination={ot.pagination} onPage={ot.setPage} /></Body></Card>
      <Card className="!p-0"><Bar><p className="text-sm text-[#5b6b7b]">Advances are recovered monthly and never push net pay below zero.</p><button className={`${btnPrimary} ms-auto`} onClick={() => setA({ kind: 'advances', employeeId: '', amount: '', monthlyRecovery: '', reason: '' })}>Request advance</button></Bar>
        <Body l={adv} cols={5} empty={{ title: 'No advances' }}><Tbl head={['Person', 'Amount', 'Per month', 'Recovered', 'Status', '']}>{adv.rows.map((x) => <Row key={x._id}><Td>{x.employeeName}<div className="text-xs text-[#5b6b7b]">{x.reason}</div></Td><Td>{pkr(x.amount)}</Td><Td>{pkr(x.monthlyRecovery)}</Td><Td>{pkr(x.recovered)}</Td><Td><Pill value={TONE[x.status]}>{x.status}</Pill></Td><Td cls="text-end whitespace-nowrap">{x.status === 'Requested' && <><button className="text-xs font-semibold text-[#2a5cac]" onClick={() => decide('advances', x, 'approve', adv.reload)}>Approve</button><button className="ms-3 text-xs font-semibold text-[#9f1239]" onClick={() => decide('advances', x, 'reject', adv.reload)}>Reject</button></>}</Td></Row>)}</Tbl></Body></Card>
      {a && <Modal title={a.kind === 'overtime' ? 'Record overtime' : 'Request an advance'} onClose={() => setA(null)}><div className="grid gap-3 sm:grid-cols-2"><div className="sm:col-span-2"><Field label="Person"><EmpSelect emps={emps} value={a.employeeId} onChange={(v) => setA({ ...a, employeeId: v })} /></Field></div>
        {a.kind === 'overtime' ? <><Field label="Day"><input type="date" className={inputCls} value={a.date} max={today()} onChange={(e) => setA({ ...a, date: e.target.value })} /></Field><Field label="Hours" hint="In halves, up to 12"><input inputMode="decimal" className={inputCls} value={a.hours} onChange={(e) => setA({ ...a, hours: e.target.value })} /></Field></> : <><Field label="Amount (Rs)"><input inputMode="numeric" className={inputCls} value={a.amount} onChange={(e) => setA({ ...a, amount: e.target.value })} /></Field><Field label="Recovered per month (Rs)"><input inputMode="numeric" className={inputCls} value={a.monthlyRecovery} onChange={(e) => setA({ ...a, monthlyRecovery: e.target.value })} /></Field></>}
        <div className="sm:col-span-2"><Field label="Reason"><input className={inputCls} value={a.reason} onChange={(e) => setA({ ...a, reason: e.target.value })} /></Field></div></div><div className="mt-4 flex justify-end gap-2"><button className={btnGhost} onClick={() => setA(null)}>Cancel</button><button className={btnPrimary} disabled={!a.employeeId} onClick={act(() => apiClient.post(`/hr/${a.kind}`, a.kind === 'overtime' ? { employeeId: a.employeeId, date: a.date, hours: Number(a.hours), reason: a.reason } : { employeeId: a.employeeId, amount: Number(a.amount), monthlyRecovery: Number(a.monthlyRecovery), reason: a.reason }), 'Sent for approval', () => { setA(null); ot.reload(); adv.reload(); })}>Send</button></div></Modal>}
    </div>
  );
};

/* ───────── payroll ───────── */
const Payslip = ({ batchId, employeeId, onClose }) => {
  const [d, setD] = useState(null); useEffect(() => { apiClient.get(`/hr/payroll/batches/${batchId}/payslips/${employeeId}`).then((r) => setD(r.data.payslip)).catch((e) => { toast.error(errMsg(e)); onClose(); }); }, [batchId, employeeId, onClose]);
  if (!d) return <Modal title="Payslip" onClose={onClose}><div className="skeleton h-40" /></Modal>; const l = d.line;
  return (
    <Modal title={`Payslip ${d.period}`} onClose={onClose}>
      <style>{'@media print{body *{visibility:hidden}.slip,.slip *{visibility:visible}.slip{position:absolute;inset:0;padding:24px}.noprint{display:none}}'}</style>
      <div className="slip space-y-2 text-sm"><p className="text-base font-bold">{d.school.name}</p><p>{d.employee.name} · {d.employee.code} · {d.employee.department || d.employee.kind}</p>
        <table className="w-full"><tbody><tr><td>Basic salary</td><td className="text-end" dir="ltr">{pkr(l.basic)}</td></tr><tr><td>Allowances</td><td className="text-end" dir="ltr">{pkr(l.allowances)}</td></tr>{l.overtime > 0 && <tr><td>Overtime</td><td className="text-end" dir="ltr">{pkr(l.overtime)}</td></tr>}<tr className="border-t border-[#e3e7e7] font-semibold"><td>Gross</td><td className="text-end" dir="ltr">{pkr(l.gross)}</td></tr>
          {l.absenceDeduction > 0 && <tr><td>Unpaid days ({l.unpaidDays})</td><td className="text-end" dir="ltr">− {pkr(l.absenceDeduction)}</td></tr>}{l.deductions.map((x, i) => <tr key={i}><td>{x.name}</td><td className="text-end" dir="ltr">− {pkr(x.amount)}</td></tr>)}{l.tax > 0 && <tr><td>Income tax</td><td className="text-end" dir="ltr">− {pkr(l.tax)}</td></tr>}{l.advance > 0 && <tr><td>Advance recovery</td><td className="text-end" dir="ltr">− {pkr(l.advance)}</td></tr>}
          <tr className="border-t border-[#e3e7e7] text-base font-bold"><td>Net pay</td><td className="text-end" dir="ltr">{pkr(l.net)}</td></tr></tbody></table><p className="text-xs text-[#5b6b7b]">Prepared by {d.preparedBy}, finalized by {d.finalizedBy} on {fmtDate(d.finalizedAt)}.</p></div>
      <div className="noprint mt-4 flex justify-end gap-2"><button className={btnGhost} onClick={onClose}>Close</button><button className={btnPrimary} onClick={() => window.print()}><Printer className="h-4 w-4" />Print</button></div>
    </Modal>
  );
};
const Payroll = () => {
  const rules = useList('/hr/payroll/rules', 'rules'); const [batches, setBatches] = useState([]); const [open, setOpen] = useState(null); const [slip, setSlip] = useState(null); const [period, setPeriod] = useState(today().slice(0, 7)); const [nr, setNr] = useState(null);
  const loadB = useCallback(() => apiClient.get('/hr/payroll/batches').then((r) => setBatches(r.data.batches)).catch(() => {}), []); useEffect(() => { loadB(); }, [loadB]);
  const openBatch = async (id) => { try { setOpen((await apiClient.get(`/hr/payroll/batches/${id}`)).data); } catch (e) { toast.error(errMsg(e)); } };
  const prepare = async () => { try { const r = await apiClient.post('/hr/payroll/batches', { period }); toast.success(r.data.unreviewedRules ? `Prepared. ${r.data.unreviewedRules} rules still need review.` : 'Prepared'); loadB(); openBatch(r.data.batch._id); } catch (e) { toast.error(errMsg(e)); } };
  return (
    <div className="space-y-4">
      <Card><div className="flex flex-wrap items-end gap-3"><Field label="Month"><input type="month" className={`${inputCls} !w-44`} value={period} onChange={(e) => setPeriod(e.target.value)} /></Field><button className={btnPrimary} onClick={prepare}>Prepare payroll</button><p className="text-sm text-[#5b6b7b]">The person who prepares a run cannot finalize it.</p></div></Card>
      <Card className="!p-0"><div className="border-b border-[#e3e7e7] p-3 font-semibold">Payroll runs</div>{batches.length ? <Tbl head={['Month', 'People', 'Gross', 'Net', 'Status', '']}>{batches.map((b) => <Row key={b._id}><Td cls="font-medium">{b.period}</Td><Td>{b.totals.employees}</Td><Td>{pkr(b.totals.gross)}</Td><Td>{pkr(b.totals.net)}</Td><Td><Pill value={b.status === 'Finalized' ? 'Paid' : 'Pending'}>{b.status}</Pill><div className="text-xs text-[#5b6b7b]">{b.finalizedByName ? `by ${b.finalizedByName}` : `prepared by ${b.preparedByName}`}</div></Td><Td cls="text-end"><button className="text-xs font-semibold text-[#2a5cac]" onClick={() => openBatch(b._id)}>Open</button></Td></Row>)}</Tbl> : <EmptyState title="No payroll runs yet" text="Prepare a month to see each person’s pay, deductions and exceptions." />}</Card>
      <Card className="!p-0"><Bar><p className="text-sm text-[#5b6b7b]">Deductions and tax follow your local law. Enter them, then another admin or your accountant reviews each one. Nothing is built in.</p><button className={`${btnPrimary} ms-auto`} onClick={() => setNr({ name: '', kind: 'percent-of-basic', value: '', slabs: [{ upTo: '', ratePercent: '', fixed: '' }] })}>New rule</button></Bar>
        <Body l={rules} cols={4} empty={{ title: 'No pay rules', text: 'Add provident fund, tax bands or fixed deductions.' }}><Tbl head={['Rule', 'Detail', 'Status', '']}>{rules.rows.map((r) => <Row key={r._id}><Td className="font-medium">{r.name}</Td><Td>{r.kind === 'tax-slabs' ? `${r.slabs.length} tax bands` : r.kind === 'fixed' ? pkr(r.value) : `${r.value}% of ${r.kind === 'percent-of-gross' ? 'gross' : 'basic'}`}{r.reviewedByName && <div className="text-xs text-[#5b6b7b]">Reviewed by {r.reviewedByName}: {r.reviewNote}</div>}</Td><Td><Pill value={TONE[r.status]}>{r.status}</Pill></Td><Td cls="text-end whitespace-nowrap">{r.status === 'Draft' && <button className="text-xs font-semibold text-[#2a5cac]" onClick={() => { const note = window.prompt('What did you check it against? (for example the current schedule)'); if (note) act(() => apiClient.post(`/hr/payroll/rules/${r._id}/review`, { note }), 'Reviewed', rules.reload)(); }}>Review</button>}{r.status !== 'Retired' && <button className="ms-3 text-xs font-semibold text-[#5b6b7b]" onClick={act(() => apiClient.post(`/hr/payroll/rules/${r._id}/review`, { retire: true }), 'Retired', rules.reload)}>Retire</button>}</Td></Row>)}</Tbl></Body></Card>
      {open && <Modal title={`Payroll ${open.batch.period}`} onClose={() => setOpen(null)} wide>
        <div className="space-y-3 text-sm"><div className="flex flex-wrap items-center gap-3"><Pill value={open.batch.status === 'Finalized' ? 'Paid' : 'Pending'}>{open.batch.status}</Pill><span>Gross {pkr(open.batch.totals.gross)} · Net {pkr(open.batch.totals.net)}</span>{open.batch.status === 'Draft' && <><button className={`${btnPrimary} ms-auto`} disabled={!open.canFinalize} title={open.canFinalize ? '' : 'You prepared this run. Another admin must finalize it.'} onClick={act(() => apiClient.post(`/hr/payroll/batches/${open.batch._id}/finalize`), 'Payroll finalized', () => { setOpen(null); loadB(); })}>Finalize</button><button className={btnGhost} onClick={act(() => apiClient.delete(`/hr/payroll/batches/${open.batch._id}`), 'Discarded', () => { setOpen(null); loadB(); })}>Discard</button></>}</div>
          {open.batch.status === 'Draft' && !open.canFinalize && <p className="text-[#8a4636]">You prepared this run. Another admin must finalize it.</p>}
          <Tbl head={['Person', 'Gross', 'Deductions', 'Net', 'Notes', '']}>{open.batch.lines.map((l) => <Row key={l.employeeId}><Td><b>{l.name}</b><div className="text-xs text-[#5b6b7b]">{l.code}</div></Td><Td>{pkr(l.gross)}</Td><Td>{pkr(l.absenceDeduction + l.advance + l.tax + l.deductions.reduce((t, d) => t + d.amount, 0))}</Td><Td cls="font-semibold">{pkr(l.net)}</Td><Td cls="max-w-[18rem] text-xs text-[#8a4636]">{l.exceptions.join(' ')}</Td><Td cls="text-end">{open.batch.status === 'Finalized' && <button className="text-xs font-semibold text-[#2a5cac]" onClick={() => setSlip(l.employeeId)}>Payslip</button>}</Td></Row>)}</Tbl></div>
        {slip && <Payslip batchId={open.batch._id} employeeId={slip} onClose={() => setSlip(null)} />}</Modal>}
      {nr && <Modal title="New pay rule" onClose={() => setNr(null)}><div className="space-y-3"><Field label="Name"><input className={inputCls} value={nr.name} onChange={(e) => setNr({ ...nr, name: e.target.value })} /></Field><Field label="Kind"><select className={inputCls} value={nr.kind} onChange={(e) => setNr({ ...nr, kind: e.target.value })}><option value="percent-of-basic">Percent of basic</option><option value="percent-of-gross">Percent of gross</option><option value="fixed">Fixed amount</option><option value="tax-slabs">Income tax bands</option></select></Field>
        {nr.kind !== 'tax-slabs' ? <Field label={nr.kind === 'fixed' ? 'Rupees' : 'Percent'}><input inputMode="decimal" className={inputCls} value={nr.value} onChange={(e) => setNr({ ...nr, value: e.target.value })} /></Field> : <div className="space-y-2"><p className="text-xs text-[#5b6b7b]">Annual taxable income. Each band: up to, rate on the amount above the previous band, plus a fixed amount. The last band has no upper limit.</p>{nr.slabs.map((s, i) => <div key={i} className="grid grid-cols-3 gap-2"><input className={inputCls} placeholder="Up to (Rs)" value={s.upTo} onChange={(e) => setNr({ ...nr, slabs: nr.slabs.map((x, j) => (j === i ? { ...x, upTo: e.target.value } : x)) })} /><input className={inputCls} placeholder="Rate %" value={s.ratePercent} onChange={(e) => setNr({ ...nr, slabs: nr.slabs.map((x, j) => (j === i ? { ...x, ratePercent: e.target.value } : x)) })} /><input className={inputCls} placeholder="Fixed Rs" value={s.fixed} onChange={(e) => setNr({ ...nr, slabs: nr.slabs.map((x, j) => (j === i ? { ...x, fixed: e.target.value } : x)) })} /></div>)}<button className="text-xs font-semibold text-[#2a5cac]" onClick={() => setNr({ ...nr, slabs: [...nr.slabs, { upTo: '', ratePercent: '', fixed: '' }] })}>Add a band</button></div>}</div>
        <div className="mt-4 flex justify-end gap-2"><button className={btnGhost} onClick={() => setNr(null)}>Cancel</button><button className={btnPrimary} disabled={nr.name.trim().length < 2} onClick={act(() => apiClient.post('/hr/payroll/rules', nr.kind === 'tax-slabs' ? { name: nr.name, kind: nr.kind, slabs: nr.slabs.map((s) => ({ upTo: s.upTo === '' ? undefined : Number(s.upTo), ratePercent: Number(s.ratePercent), fixed: Number(s.fixed || 0) })) } : { name: nr.name, kind: nr.kind, value: Number(nr.value) }), 'Saved. Another admin must review it.', () => { setNr(null); rules.reload(); })}>Save</button></div></Modal>}
    </div>
  );
};

/* ───────── exits ───────── */
const Exits = () => {
  const [rows, setRows] = useState(null); const load = useCallback(() => apiClient.get('/hr/settlements').then((r) => setRows(r.data.settlements)).catch((e) => toast.error(errMsg(e))), []); useEffect(() => { load(); }, [load]);
  if (!rows) return <div className="skeleton h-32" />; if (!rows.length) return <Card><EmptyState title="No settlements" text="Open a staff member and choose Start final settlement when someone leaves." /></Card>;
  return (
    <div className="space-y-3">{rows.map((s) => (
      <Card key={s._id}><div className="flex flex-wrap items-center gap-3"><p className="font-semibold">{s.employeeName}</p><Pill value={TONE[s.status]}>{s.status}</Pill><span className="text-sm text-[#5b6b7b]">last day {s.lastDay} · {s.reason}</span></div>
        <p className="mt-2 text-sm">Salary due {pkr(s.salaryDue)} + leave pay {pkr(s.leaveEncashment)} − advances {pkr(s.advanceRecovery)} = <b>{pkr(s.net)}</b></p>
        <ul className="mt-2 grid gap-1 sm:grid-cols-2">{s.clearance.map((c) => <li key={c.key}><label className="flex items-center gap-2 text-sm"><input type="checkbox" disabled={s.status !== 'Open'} checked={c.cleared} onChange={(e) => act(() => apiClient.put(`/hr/settlements/${s._id}/clear/${c.key}`, { cleared: e.target.checked }), null, load)()} />{c.label}</label></li>)}</ul>
        {s.status === 'Open' && <div className="mt-3 flex justify-end"><button className={btnPrimary} onClick={act(() => apiClient.post(`/hr/settlements/${s._id}/settle`), 'Settled. The employee has left.', load)}>Close settlement</button></div>}</Card>))}</div>
  );
};

/* ───────── setup ───────── */
const Setup = () => {
  const [pos, setPos] = useState([]); const [np, setNp] = useState(null); const [st, setSt] = useState(null);
  const load = useCallback(() => { apiClient.get('/hr/positions').then((r) => setPos(r.data.positions)).catch(() => {}); apiClient.get('/hr/settings').then((r) => setSt(r.data.settings)).catch(() => {}); }, []); useEffect(() => { load(); }, [load]);
  return (
    <div className="space-y-4">
      <Card className="!p-0"><Bar><p className="text-sm text-[#5b6b7b]">Positions carry the salary band. Pay outside the band is refused.</p><button className={`${btnPrimary} ms-auto`} onClick={() => setNp({ title: '', department: '', grade: '', salaryMin: '', salaryMax: '' })}>New position</button></Bar>
        {pos.length ? <Tbl head={['Position', 'Department', 'Band', 'Holders', '']}>{pos.map((p) => <Row key={p._id}><Td cls="font-medium">{p.title}{p.status === 'Retired' && <span className="ms-2 text-xs text-[#5b6b7b]">retired</span>}</Td><Td>{p.department || '—'}</Td><Td>{p.salaryMax ? `${pkr(p.salaryMin)} – ${pkr(p.salaryMax)}` : 'Not set'}</Td><Td>{p.holders}</Td><Td cls="text-end">{p.status === 'Active' && <button className="text-xs font-semibold text-[#5b6b7b]" onClick={act(() => apiClient.put(`/hr/positions/${p._id}`, { retire: true }), 'Retired', load)}>Retire</button>}</Td></Row>)}</Tbl> : <EmptyState title="No positions" />}</Card>
      {st && <Card><p className="font-semibold">Leave and pay settings</p><div className="mt-3 grid gap-3 sm:grid-cols-3 lg:grid-cols-6">{[['annual', 'Annual leave days'], ['sick', 'Sick leave days'], ['casual', 'Casual leave days'], ['overtimeMultiplier', 'Overtime multiple'], ['lateGraceMinutes', 'Late after (min)'], ['maxAdvanceMultiple', 'Advance cap (months)']].map(([k, label]) => <Field key={k} label={label}><input inputMode="decimal" className={inputCls} value={st[k]} onChange={(e) => setSt({ ...st, [k]: e.target.value })} /></Field>)}</div><div className="mt-3"><button className={btnGhost} onClick={act(() => apiClient.put('/hr/settings', Object.fromEntries(Object.entries(st).map(([k, v]) => [k, Number(v)]))), 'Saved')}>Save settings</button></div></Card>}
      {np && <Modal title="New position" onClose={() => setNp(null)}><div className="grid gap-3 sm:grid-cols-2">{[['title', 'Title'], ['department', 'Department'], ['grade', 'Grade'], ['salaryMin', 'Band from (Rs)'], ['salaryMax', 'Band to (Rs)']].map(([k, l]) => <Field key={k} label={l}><input className={inputCls} value={np[k]} onChange={(e) => setNp({ ...np, [k]: e.target.value })} /></Field>)}</div><div className="mt-4 flex justify-end gap-2"><button className={btnGhost} onClick={() => setNp(null)}>Cancel</button><button className={btnPrimary} disabled={np.title.trim().length < 2} onClick={act(() => apiClient.post('/hr/positions', { ...np, salaryMin: Number(np.salaryMin) || 0, salaryMax: Number(np.salaryMax) || 0 }), 'Saved', () => { setNp(null); load(); })}>Save</button></div></Modal>}
    </div>
  );
};

const TABS = [['overview', 'Overview'], ['people', 'People'], ['roster', 'Roster'], ['attendance', 'Attendance'], ['leave', 'Leave & cover'], ['time', 'Overtime & advances'], ['payroll', 'Payroll'], ['exits', 'Exits'], ['setup', 'Setup']];
export default function Staff({ open }) {
  // `open` lets the sidebar point straight at one part, for example staff attendance, which
  // people were not finding under a tab called "Staff and payroll".
  const [tab, setTab] = useState(TABS.some(([id]) => id === open) ? open : 'overview');
  useEffect(() => { if (open && TABS.some(([id]) => id === open)) setTab(open); }, [open]);
  const body = { overview: <Overview onGo={setTab} />, people: <People />, roster: <Roster />, attendance: <Attendance />, leave: <Leave />, time: <Time />, payroll: <Payroll />, exits: <Exits />, setup: <Setup /> }[tab];
  return (
    <div className="space-y-4">
      <div><h2 className="text-xl font-bold text-[#1b2837]">Staff and payroll</h2><p className="text-sm text-[#5b6b7b]">People, contracts, roster, leave and cover, overtime, and a payroll that two people must sign off.</p></div>
      <div className="flex gap-1 overflow-x-auto border-b border-[#e3e7e7]" role="tablist">{TABS.map(([id, label]) => <button key={id} role="tab" aria-selected={tab === id} onClick={() => setTab(id)} className={`whitespace-nowrap border-b-2 px-3 py-2 text-sm font-semibold transition ${tab === id ? 'border-[#2a5cac] text-[#2a5cac]' : 'border-transparent text-[#5b6b7b] hover:text-[#1b2837]'}`}>{label}</button>)}</div>
      {body}
    </div>
  );
}
